<script setup lang="ts">
import { useVfm, VueFinalModal } from 'vue-final-modal'
import { useImkitStore } from '../stores/imkit'
import Folder from './../classes/folder'

const vfm = useVfm()
const props = defineProps<{ folder: Folder }>()
const imkit = useImkitStore()
const confirm = (folderId: string) => {
  imkit.removeFolder(folderId)
}
</script>

<template>
  <vue-final-modal
    class="flex items-center justify-center"
    content-class="bg-white dark:bg-zinc-800 min-w-[200px] max-w-full rounded-xl p-5 flex flex-col gap-3 max-w-[360px]"
    content-transition="vfm-fade"
    overlay-transition="vfm-fade"
  >
    <div
      class="mb-1 flex items-center justify-between text-xl font-medium text-gray-700 dark:text-gray-300"
    >
      {{ $t('confirmToDeleteFolder') }}
    </div>
    <div class="flex items-center justify-center gap-2">
      <button
        class="disabled:(bg-blue-200 cursor-not-allowed) h-10 w-[100px] grow rounded-lg border border-gray-200 text-base dark:border-stone-400 dark:text-stone-400"
        @click="
          () => {
            vfm.closeAll()
          }
        "
      >
        {{ $t('cancel') }}
      </button>
      <button
        class="disabled:(bg-blue-200 cursor-not-allowed) h-10 w-[100px] grow rounded-lg bg-blue-400 text-base text-white"
        @click="
          () => {
            confirm(props.folder.id)
            vfm.closeAll()
          }
        "
      >
        {{ $t('confirm') }}
      </button>
    </div>
  </vue-final-modal>
</template>
