/**
 * Web Component (custom element) wrappers around the IMKIT Vue SDK.
 *
 * Exposed elements:
 *   <imkit-chat-room>          — main message thread + input
 *   <imkit-room-list>          — left-pane room list with search/sort
 *   <imkit-chat-room-info>     — right-pane room/member info panel
 *   <imkit-modals-container>   — page-level modal mount point
 *
 * All four share a single Pinia store at the module level. Clicking a room
 * in <imkit-room-list> updates selectedRoomId; the sibling <imkit-chat-room>
 * re-renders, and <imkit-chat-room-info> auto-shows. Modal confirmations
 * (delete room, etc.) get a teleport target via <imkit-modals-container>.
 *
 * Mounted into light DOM (no shadow root) on purpose: vue-final-modal
 * teleports modal markup to document.body, and shadow-encapsulated styles
 * cannot reach those teleported nodes. Tradeoff: page-level styles can
 * leak in.
 */
import * as jose from 'jose'
import { createPinia, type Pinia } from 'pinia'
import type { App, Component } from 'vue'
import { computed, createApp, defineComponent, h, markRaw, reactive } from 'vue'
import { ModalsContainer } from 'vue-final-modal'
import Callbacks from './classes/callbacks'
import Config from './classes/config'
import Settings from './classes/settings'
import Styles from './classes/styles'
import ChatRoom from './components/ChatRoom.vue'
import ChatRoomInfo from './components/ChatRoomInfo.vue'
import RoomList from './components/RoomList.vue'
import IMKitPlugin, { installAppLevel } from './lib'
import { getConfig } from './runtime/config'
import { getSocket } from './runtime/socket'
import { setUid } from './runtime/uid'
import { type ImkitStore, useImkitStore } from './stores/imkit'

const CHAT_ROOM_ELEMENT_NAME = 'imkit-chat-room'
const ROOM_LIST_ELEMENT_NAME = 'imkit-room-list'
const CHAT_ROOM_INFO_ELEMENT_NAME = 'imkit-chat-room-info'
const MODALS_CONTAINER_ELEMENT_NAME = 'imkit-modals-container'

const ATTR_TOKEN = 'token'
const ATTR_API_BASE_URL = 'api-base-url'
const ATTR_CLIENT_KEY = 'client-key'
const ATTR_ROOM_ID = 'room-id'
const ATTR_ROOM_TAG = 'room-tag'
const ATTR_THEME = 'theme'

const COMMON_OBSERVED_ATTRIBUTES = [
  ATTR_TOKEN,
  ATTR_API_BASE_URL,
  ATTR_CLIENT_KEY,
  ATTR_ROOM_TAG,
  ATTR_THEME
] as const

const ROOM_AWARE_OBSERVED_ATTRIBUTES = [
  ...COMMON_OBSERVED_ATTRIBUTES,
  ATTR_ROOM_ID
] as const

type AttrName = (typeof ROOM_AWARE_OBSERVED_ATTRIBUTES)[number]

const defaultSettings = (): Settings => ({
  locationInputEnabled: true,
  audioInputEnabled: true,
  fileInputEnabled: true,
  emojiInputEnabled: true,
  stickerInputEnabled: true,
  sendButtonEnabled: true,
  searchInRoomEnabled: true,
  showDirectChatRoomInfoButton: true,
  showGroupChatRoomInfoButton: true,
  autoSelectRoomWhenLoaded: false,
  customRoomInfoIframeURL: '',
  showLeaveRoomButton: false,
  showMemberActionMenu: true,
  massTextingEnabled: false,
  showDarkModeSwitch: false,
  enableReadReceipt: true,
  linkPreviewEnabled: true
})

const defaultStyles = (): Styles => ({
  incomingMessageCell: '',
  outgoingMessageCell: '',
  roomListUnreadBadge: '',
  chatRoomHeader: '',
  sendButtonEnabled: '',
  sendButtonDisabled: ''
})

const defaultCallbacks = (): Callbacks => ({
  onMessageReceived: () => {},
  onMessageSent: () => {}
})

const buildConfig = (
  attrs: Partial<Record<AttrName, string>>,
  overrides: Partial<Config>
): Config => ({
  domain: attrs[ATTR_API_BASE_URL] ?? '',
  clientKey: attrs[ATTR_CLIENT_KEY] ?? '',
  token: attrs[ATTR_TOKEN] ?? '',
  translationApiKey: '',
  mapApiKey: '',
  firebaseConfig: null,
  firebaseVapidKey: undefined,
  settings: defaultSettings(),
  styles: defaultStyles(),
  callbacks: defaultCallbacks(),
  ...overrides
})

// ---------------------------------------------------------------------------
// Shared store across element instances.
//
// First element to mount creates the singleton AND runs the full
// IMKitPlugin install (builds axios + socket, initializes the Pinia store,
// and registers per-app pieces on its own Vue app).
// Subsequent elements reuse the singleton store and call only
// `installAppLevel(app)` for their own Vue app, avoiding duplicate sockets.
//
// A refcount tracks live elements; when it drops to zero we tear down the
// socket and clear the singleton so a future remount starts fresh.
// ---------------------------------------------------------------------------

let sharedPinia: Pinia | undefined
let sharedStore: ImkitStore | undefined
let sharedStoreInitialized = false
let sharedRefcount = 0

const getOrCreateSharedPinia = (): Pinia => {
  if (!sharedPinia) sharedPinia = createPinia()
  return sharedPinia
}

const getOrCreateSharedStore = (pinia: Pinia): ImkitStore => {
  if (!sharedStore) sharedStore = useImkitStore(pinia)
  return sharedStore
}

const releaseSharedStore = (): void => {
  sharedRefcount = Math.max(0, sharedRefcount - 1)
  if (sharedRefcount > 0 || !sharedStore) return
  try {
    getSocket().disconnect()
  } catch {
    /* ignore */
  }
  sharedPinia = undefined
  sharedStore = undefined
  sharedStoreInitialized = false
}

const decodeUid = (token: string): string => {
  try {
    const { id, _id } = jose.decodeJwt(token)
    const rawUid = id ?? _id
    return typeof rawUid === 'string' ? rawUid : ''
  } catch (e) {
    console.log(e)
    return ''
  }
}

const applyRuntimeConfigPatch = (config: Partial<Config>): void => {
  try {
    Object.assign(getConfig(), config)
  } catch {
    return
  }
  if (typeof config.token === 'string') {
    setUid(decodeUid(config.token))
  }
}

const getRuntimeToken = (): string | undefined => {
  try {
    return getConfig().token
  } catch {
    return undefined
  }
}

const reconnectSocket = (): void => {
  try {
    const socket = getSocket()
    socket.disconnect()
    socket.connect()
  } catch {
    /* runtime is not initialized yet */
  }
}

// ---------------------------------------------------------------------------
// Base element shared by all four element classes.
// ---------------------------------------------------------------------------

interface IMKitElementImperativeAPI {
  setConfig(config: Partial<Config>): void
  setRoomTag(tag: string): void
  getStore(): ImkitStore | undefined
  readonly imkitReady: boolean
}

abstract class IMKitElementBase
  extends HTMLElement
  implements IMKitElementImperativeAPI
{
  protected app?: App
  protected store?: ImkitStore
  protected mountPoint?: HTMLDivElement
  protected overrides: Partial<Config> = {}
  protected themeState = reactive<{ theme: string | null }>({ theme: null })
  private storeUnsubscribe?: () => void
  private actionUnsubscribe?: () => void
  private _imkitReady = false

  protected abstract getElementLabel(): string

  /** Override to swap the inner Vue component. Return null for elements that
   *  only need the modals container (e.g. <imkit-modals-container>). */
  protected getRootComponent(): Component | null {
    return null
  }

  /** Render an inline ModalsContainer next to the root component. Off for
   *  <imkit-chat-room-info> since the page already has a sibling
   *  <imkit-modals-container>. On for everyone else. */
  protected includesInlineModals(): boolean {
    return true
  }

  /** Auto-hide the root component when there's no selected room. Used by
   *  <imkit-chat-room-info> to match v1's `v-if="selectedRoomId"`. */
  protected hideRootWhenNoSelectedRoom(): boolean {
    return false
  }

  /** Hook fired after the inner Vue app has mounted. */
  protected onAfterMount?(store: ImkitStore): void

  /** Public: set by the base class once mount() resolves. React consumers
   *  can read this synchronously to recover from missing the imkit-ready
   *  event (event-only signaling races against React effect phases). */
  get imkitReady(): boolean {
    return this._imkitReady
  }

  connectedCallback(): void {
    if (this.app) return
    this.themeState.theme = this.getAttribute(ATTR_THEME)
    this.mount()
  }

  disconnectedCallback(): void {
    this.unmount()
  }

  attributeChangedCallback(
    name: string,
    oldVal: string | null,
    newVal: string | null
  ): void {
    if (oldVal === newVal) return
    const store = this.store
    switch (name) {
      case ATTR_THEME:
        this.themeState.theme = newVal
        break
      case ATTR_ROOM_ID:
        if (store) store.$patch({ selectedRoomId: newVal ?? '' })
        break
      case ATTR_ROOM_TAG:
        if (store) store.setRoomTag(newVal ?? '')
        break
      case ATTR_TOKEN:
        if (store) {
          const currentToken = getRuntimeToken()
          if (currentToken === newVal) break
          applyRuntimeConfigPatch({ token: newVal ?? '' })
          reconnectSocket()
        }
        break
      case ATTR_API_BASE_URL:
      case ATTR_CLIENT_KEY:
        // Changing these would require rebuilding axios/socket for the shared
        // runtime, which would also invalidate any sibling element. Out of
        // scope for runtime updates; consumers should set these once at
        // first mount.
        console.warn(
          `[${this.getElementLabel()}] ${name} changed at runtime; ignored. ` +
            `Set this attribute once before the element first connects.`
        )
        break
    }
  }

  protected currentAttrs(): Partial<Record<AttrName, string>> {
    const result: Partial<Record<AttrName, string>> = {}
    for (const name of ROOM_AWARE_OBSERVED_ATTRIBUTES) {
      const v = this.getAttribute(name)
      if (v !== null) result[name] = v
    }
    return result
  }

  protected mount(): void {
    const config = buildConfig(this.currentAttrs(), this.overrides)
    const pinia = getOrCreateSharedPinia()
    const store = getOrCreateSharedStore(pinia)
    const initialRoomId = this.getAttribute(ATTR_ROOM_ID) ?? ''
    const initialRoomTag = this.getAttribute(ATTR_ROOM_TAG) ?? ''
    const themeState = this.themeState
    const rootComponent = this.getRootComponent()
    const includeInlineModals = this.includesInlineModals()
    const hideRootWhenNoSelectedRoom = this.hideRootWhenNoSelectedRoom()

    const Wrapper = defineComponent({
      name: 'IMKitElementCE',
      setup() {
        const RootComp = rootComponent ? markRaw(rootComponent) : null
        const ModalsContainerComp = markRaw(
          ModalsContainer as unknown as Component
        )
        const imkit = useImkitStore()
        const showRoot = computed(() => {
          if (!RootComp) return false
          if (!hideRootWhenNoSelectedRoom) return true
          return !!imkit.selectedRoomId
        })
        return () => {
          const children = []
          if (showRoot.value && RootComp) children.push(h(RootComp))
          if (includeInlineModals) children.push(h(ModalsContainerComp))
          return h(
            'div',
            {
              class: [
                'imkit-element-ce relative h-full w-full',
                themeState.theme === 'dark' ? 'dark' : ''
              ]
            },
            children
          )
        }
      }
    })

    const mountPoint = document.createElement('div')
    mountPoint.style.height = '100%'
    mountPoint.style.width = '100%'
    this.appendChild(mountPoint)
    this.mountPoint = mountPoint

    const app = createApp(Wrapper)
    app.use(pinia)

    // First element to mount: full install (builds axios + socket,
    // initializes store, registers per-app pieces). Subsequent
    // elements reuse the shared store and only register per-app pieces.
    // Set the flag synchronously before awaiting so concurrent mounts in
    // the same tick don't both run the heavy path.
    let installPromise: Promise<unknown>
    if (!sharedStoreInitialized) {
      sharedStoreInitialized = true
      installPromise = Promise.resolve(IMKitPlugin.install(app, { config }))
    } else {
      installAppLevel(app)
      installPromise = Promise.resolve()
    }

    installPromise
      .then(() => {
        if (initialRoomTag) {
          store.setRoomTag(initialRoomTag)
        }
        if (initialRoomId) {
          store.$patch({ selectedRoomId: initialRoomId })
        }
        this.bridgeStoreEvents(store)
        app.mount(mountPoint)
        this.onAfterMount?.(store)
        this._imkitReady = true
        this.dispatchEvent(new CustomEvent('imkit-ready'))
      })
      .catch((err) => {
        this.dispatchEvent(new CustomEvent('imkit-error', { detail: err }))
        console.error(`[${this.getElementLabel()}] failed to mount:`, err)
      })

    this.app = app
    this.store = store
    sharedRefcount++
  }

  protected unmount(): void {
    this._imkitReady = false
    this.storeUnsubscribe?.()
    this.actionUnsubscribe?.()
    this.storeUnsubscribe = undefined
    this.actionUnsubscribe = undefined
    try {
      this.app?.unmount()
    } catch (err) {
      console.warn(`[${this.getElementLabel()}] unmount error:`, err)
    }
    this.mountPoint?.remove()
    this.mountPoint = undefined
    this.app = undefined
    this.store = undefined
    releaseSharedStore()
  }

  private bridgeStoreEvents(store: ImkitStore): void {
    let prevSelectedRoomId = store.selectedRoomId
    this.storeUnsubscribe = store.$subscribe((_mutation, state) => {
      const newId = state.selectedRoomId
      if (newId === prevSelectedRoomId) return
      this.dispatchEvent(
        new CustomEvent('room-selected', {
          detail: { roomId: newId }
        })
      )
      // Synthesize go-back: in v1 the back button on <ChatRoom> clears
      // selectedRoomId. This element fires `go-back` on that exact
      // transition (non-empty -> empty). The SDK component itself does
      // not emit anything, so this is the closest faithful proxy.
      if (prevSelectedRoomId && !newId) {
        this.dispatchEvent(
          new CustomEvent('go-back', {
            detail: { fromRoomId: prevSelectedRoomId }
          })
        )
      }
      prevSelectedRoomId = newId
    })
    this.actionUnsubscribe = store.$onAction(({ name, args, after }) => {
      if (name === 'pushMessage') {
        const [message] = args
        after(() => {
          if (
            message &&
            typeof message === 'object' &&
            'roomId' in message &&
            message.roomId === store.selectedRoomId
          ) {
            this.dispatchEvent(
              new CustomEvent('message-received', { detail: message })
            )
          }
        })
      } else if (name === 'sendMessage') {
        const [payload] = args
        after(() => {
          this.dispatchEvent(
            new CustomEvent('message-sent', { detail: payload })
          )
        })
      }
    })
  }

  // -------------------------------------------------------------------------
  // Imperative API
  // -------------------------------------------------------------------------

  setConfig(config: Partial<Config>): void {
    this.overrides = { ...this.overrides, ...config }
    if (!this.store) return
    applyRuntimeConfigPatch(config)
    if (config.token || config.clientKey || config.domain) reconnectSocket()
  }

  setRoomTag(tag: string): void {
    if (!this.store) {
      // Not mounted yet — queue via attribute so it's picked up on mount.
      this.setAttribute(ATTR_ROOM_TAG, tag)
      return
    }
    this.store.setRoomTag(tag)
  }

  getStore(): ImkitStore | undefined {
    return this.store
  }
}

// ---------------------------------------------------------------------------
// <imkit-chat-room>
// ---------------------------------------------------------------------------

interface IMKitChatRoomElement extends IMKitElementImperativeAPI {
  sendMessage(text: string): Promise<void>
}

class ChatRoomElement extends IMKitElementBase implements IMKitChatRoomElement {
  static get observedAttributes(): readonly string[] {
    return ROOM_AWARE_OBSERVED_ATTRIBUTES
  }

  protected getRootComponent(): Component {
    return ChatRoom as unknown as Component
  }

  protected getElementLabel(): string {
    return CHAT_ROOM_ELEMENT_NAME
  }

  async sendMessage(text: string): Promise<void> {
    const store = this.store
    if (!store) throw new Error(`${CHAT_ROOM_ELEMENT_NAME}: not mounted`)
    const roomId = store.selectedRoomId
    if (!roomId) throw new Error(`${CHAT_ROOM_ELEMENT_NAME}: no room selected`)
    await store.sendMessage({
      roomId,
      messageType: 'text',
      message: text
    })
  }
}

// ---------------------------------------------------------------------------
// <imkit-room-list>
// ---------------------------------------------------------------------------

class RoomListElement extends IMKitElementBase {
  static get observedAttributes(): readonly string[] {
    return COMMON_OBSERVED_ATTRIBUTES
  }

  protected getRootComponent(): Component {
    return RoomList as unknown as Component
  }

  protected getElementLabel(): string {
    return ROOM_LIST_ELEMENT_NAME
  }

  protected onAfterMount(store: ImkitStore): void {
    // RoomList.vue dispatches fetchRooms in its own onMounted, but a
    // standalone caller may mount the room list before any chat room and
    // expect rooms to load immediately. The dispatch is idempotent (gated
    // on isRequesting[FetchRooms] in the action), so calling it here is
    // safe and matches the user-facing spec for this element.
    store.fetchRooms().catch((err) => {
      console.warn(`[${ROOM_LIST_ELEMENT_NAME}] fetchRooms error:`, err)
    })
  }
}

// ---------------------------------------------------------------------------
// <imkit-chat-room-info>
// ---------------------------------------------------------------------------

class ChatRoomInfoElement extends IMKitElementBase {
  static get observedAttributes(): readonly string[] {
    return ROOM_AWARE_OBSERVED_ATTRIBUTES
  }

  protected getRootComponent(): Component {
    return ChatRoomInfo as unknown as Component
  }

  protected getElementLabel(): string {
    return CHAT_ROOM_INFO_ELEMENT_NAME
  }

  protected includesInlineModals(): boolean {
    // The page already has a sibling <imkit-modals-container>; rendering
    // another inline modals container here would create duplicate teleport
    // targets.
    return false
  }

  protected hideRootWhenNoSelectedRoom(): boolean {
    return true
  }
}

// ---------------------------------------------------------------------------
// <imkit-modals-container>
// ---------------------------------------------------------------------------

class ModalsContainerElement extends IMKitElementBase {
  static get observedAttributes(): readonly string[] {
    return COMMON_OBSERVED_ATTRIBUTES
  }

  protected getRootComponent(): null {
    return null // ModalsContainer-only; no sibling component
  }

  protected getElementLabel(): string {
    return MODALS_CONTAINER_ELEMENT_NAME
  }

  protected includesInlineModals(): boolean {
    return true
  }
}

// ---------------------------------------------------------------------------
// Element registration
// ---------------------------------------------------------------------------

if (typeof window !== 'undefined' && typeof customElements !== 'undefined') {
  if (!customElements.get(CHAT_ROOM_ELEMENT_NAME)) {
    customElements.define(CHAT_ROOM_ELEMENT_NAME, ChatRoomElement)
  }
  if (!customElements.get(ROOM_LIST_ELEMENT_NAME)) {
    customElements.define(ROOM_LIST_ELEMENT_NAME, RoomListElement)
  }
  if (!customElements.get(CHAT_ROOM_INFO_ELEMENT_NAME)) {
    customElements.define(CHAT_ROOM_INFO_ELEMENT_NAME, ChatRoomInfoElement)
  }
  if (!customElements.get(MODALS_CONTAINER_ELEMENT_NAME)) {
    customElements.define(MODALS_CONTAINER_ELEMENT_NAME, ModalsContainerElement)
  }
}

export {
  CHAT_ROOM_ELEMENT_NAME,
  CHAT_ROOM_INFO_ELEMENT_NAME,
  ChatRoomElement,
  ChatRoomInfoElement,
  MODALS_CONTAINER_ELEMENT_NAME,
  ModalsContainerElement,
  ROOM_LIST_ELEMENT_NAME,
  RoomListElement
}
export default ChatRoomElement
