<script setup lang="ts">
import { computed } from 'vue'
import { useI18n } from 'vue-i18n'
import { getUid } from '../runtime/uid'
import { useImkitStore } from '../stores/imkit'
import Message, {
  MessageType,
  SystemMessage,
  TextMessage
} from './../classes/message'
const props = defineProps<{ message: Message }>()
const users = computed(() => useImkitStore().users)
const { t } = useI18n()
const text = computed(() => {
  const senderNickname = users.value[props.message.senderId]?.nickname
  switch (props.message.type) {
    case MessageType.Recall:
      if (props.message.senderId === getUid()) {
        return t('youUnsentMessage')
      }
      return t('someoneUnsentMessage', [senderNickname])
    case MessageType.JoinRoom:
      return t('someoneJoinedTheChat', [senderNickname])
    case MessageType.LeaveRoom:
      return t('someoneLeftTheChat', [senderNickname])
    case MessageType.AddMember:
      return t('someoneInvited', [
        senderNickname,
        (props.message as SystemMessage).members
          .map((member) => member.nickname)
          .join(', ')
      ])
    case MessageType.DeleteMember:
      return t('someoneKicked', [
        senderNickname,
        (props.message as SystemMessage).members
          .map((member) => member.nickname)
          .join(', ')
      ])
    case MessageType.AddMembers:
      return t('someoneInvited', [
        senderNickname,
        (props.message as SystemMessage).members
          .map((member) => member.nickname)
          .join(', ')
      ])
    case MessageType.Announcement:
      return (props.message as TextMessage).text
    default:
      return ''
  }
})
</script>

<template>
  <div class="flex items-center justify-center">
    <div
      class="my-1.5 rounded-lg bg-gray-100 px-2 py-1.5 text-base text-gray-700 dark:bg-zinc-700 dark:text-gray-200 dark:text-gray-300"
    >
      {{ text }}
    </div>
  </div>
</template>

<style scoped></style>
