<script setup lang="ts">
import { ImageOff, VideoOff } from 'lucide-vue-next'
import type { StyleValue } from 'vue'
import { onBeforeUnmount, ref, watch } from 'vue'
import {
  fetchImageAsBase64,
  refreshS3PresignedUrl,
  resolveFilesProxyUrl
} from '../../composables/useMediaFetch'
import { getAxios } from '../../runtime/axios'
import {
  addImageFailure,
  imageCache,
  imageFailuresRef,
  removeImageFailure
} from '../../runtime/caches'
import {
  dropSignedUrl,
  getSignedUrl,
  getSignedUrlEntry,
  isOnCooldown,
  markCooldown,
  setSignedUrl
} from '../../runtime/signedUrlStore'
import { useImkitStore } from '../../stores/imkit'

const NEAR_EXPIRY_THRESHOLD_MS = 5 * 60_000

type LoadState = 'idle' | 'loading' | 'loaded' | 'failed'

const props = withDefaults(
  defineProps<{
    url: string
    alt?: string
    variant?: 'thumb' | 'full'
    kind?: 'image' | 'video'
    imgClass?: string
    imgStyle?: StyleValue
    noCallout?: boolean
  }>(),
  {
    alt: '',
    variant: 'thumb',
    kind: 'image',
    imgClass: '',
    imgStyle: () => ({}),
    noCallout: false
  }
)

const emit = defineEmits<{
  (e: 'load'): void
  (e: 'error'): void
  (e: 'retry'): void
}>()

const imkit = useImkitStore()
const imageFailures = imageFailuresRef

const resolvedSrc = ref<string>('')
const state = ref<LoadState>('idle')
const triedFallbackRef = ref(false)

let loadToken = 0
let alive = true
onBeforeUnmount(() => {
  alive = false
})

const isValidUrl = (value: string): boolean => {
  if (!value) return false
  try {
    new URL(value, window.location.href)
    return true
  } catch {
    return false
  }
}

const load = async (url: string) => {
  const token = ++loadToken

  if (!url) {
    state.value = 'failed'
    emit('error')
    return
  }
  if (url.startsWith('data:')) {
    resolvedSrc.value = url
    state.value = 'loaded'
    emit('load')
    return
  }
  if (!isValidUrl(url)) {
    state.value = 'failed'
    emit('error')
    return
  }
  const cached = imageCache.get(url)
  if (cached) {
    resolvedSrc.value = cached
    state.value = 'loaded'
    emit('load')
    return
  }
  const cachedSignedUrl = getSignedUrl(url)
  if (cachedSignedUrl) {
    resolvedSrc.value = cachedSignedUrl
    state.value = 'loaded'
    emit('load')
    return
  }
  if (imageFailures.value.has(url)) {
    state.value = 'failed'
    emit('error')
    return
  }

  state.value = 'loading'
  const onProgress = (ratio: number) => {
    if (!alive || token !== loadToken) return
    imkit.mergeInto('downloadProgresses', { [url]: ratio })
  }

  // For /files/{bucket}/{id} proxy URLs, resolve to the direct storage
  // signed URL and let the browser load it natively via <img src>.
  // Bypasses the server-side pipe and avoids CORS on the storage bucket
  // (signed S3/GCS URLs often lack CORS, which blocks fetch/XHR but not
  // native image loads).
  // Skip the /files resolver after an onerror fallback — the resolver
  // just returned the now-broken signed URL we are recovering from.
  if (!triedFallbackRef.value) {
    const signedUrl = await resolveFilesProxyUrl(getAxios(), url).catch(
      () => null
    )
    if (!alive || token !== loadToken) return
    if (signedUrl) {
      setSignedUrl(url, signedUrl)
      resolvedSrc.value = signedUrl
      state.value = 'loaded'
      emit('load')
      return
    }
  }

  try {
    const src = await fetchImageAsBase64(url, onProgress)
    if (!alive || token !== loadToken) return
    imageCache.set(url, src)
    resolvedSrc.value = src
    state.value = 'loaded'
    emit('load')
    return
  } catch {
    // fall through to S3 refresh attempt
  }

  if (!alive || token !== loadToken) return

  try {
    const fresh = await refreshS3PresignedUrl(getAxios(), url)
    if (!alive || token !== loadToken) return
    if (fresh) {
      setSignedUrl(url, fresh)
      resolvedSrc.value = fresh
      state.value = 'loaded'
      emit('load')
      return
    }
  } catch {
    // fall through to failed
  }

  if (!alive || token !== loadToken) return
  addImageFailure(url)
  state.value = 'failed'
  emit('error')
}

watch(
  () => props.url,
  (url) => {
    triedFallbackRef.value = false
    load(url)
  },
  { immediate: true }
)

const onImgError = () => {
  if (triedFallbackRef.value) {
    addImageFailure(props.url)
    state.value = 'failed'
    emit('error')
    return
  }
  const entry = getSignedUrlEntry(props.url)
  const farFromExpiry =
    entry != null && Date.now() < entry.expiresAt - NEAR_EXPIRY_THRESHOLD_MS
  if (farFromExpiry) {
    addImageFailure(props.url)
    state.value = 'failed'
    emit('error')
    return
  }
  if (isOnCooldown(props.url)) {
    addImageFailure(props.url)
    state.value = 'failed'
    emit('error')
    return
  }
  markCooldown(props.url)
  dropSignedUrl(props.url)
  triedFallbackRef.value = true
  load(props.url)
}

const retry = () => {
  removeImageFailure(props.url)
  dropSignedUrl(props.url)
  triedFallbackRef.value = false
  emit('retry')
  load(props.url)
}
</script>

<template>
  <template v-if="state === 'failed'">
    <slot name="placeholder">
      <div
        v-if="variant === 'full'"
        :class="[
          'flex flex-col items-center justify-center gap-3 bg-gray-900/60 p-6 text-white',
          imgClass
        ]"
        :style="imgStyle"
        role="img"
        :aria-label="alt"
      >
        <component
          :is="kind === 'video' ? VideoOff : ImageOff"
          :size="64"
          class="text-gray-300"
        />
        <p class="text-base">{{ $t('mediaLoadFailed') }}</p>
        <button
          type="button"
          class="cursor-pointer rounded-md bg-white/10 px-4 py-2 text-base text-white hover:bg-white/20"
          @click="retry"
        >
          {{ $t('retry') }}
        </button>
      </div>
      <div
        v-else
        :class="[
          'flex items-center justify-center bg-gray-100 dark:bg-zinc-700',
          imgClass
        ]"
        :style="imgStyle"
        role="img"
        :aria-label="alt"
      >
        <component
          :is="kind === 'video' ? VideoOff : ImageOff"
          :size="32"
          class="text-gray-400 dark:text-gray-500"
        />
      </div>
    </slot>
  </template>
  <div
    v-else-if="state === 'loading'"
    :class="['bg-white dark:bg-zinc-800', imgClass]"
    :style="imgStyle"
    data-testid="media-img-loading"
  />
  <img
    v-else
    :src="resolvedSrc"
    :alt="alt"
    referrerpolicy="no-referrer"
    :draggable="noCallout ? false : undefined"
    :class="[
      imgClass,
      noCallout && '[-webkit-touch-callout:none] [-webkit-user-select:none]'
    ]"
    :style="imgStyle"
    data-testid="image-bubble-thumb"
    @error="onImgError"
  />
</template>
