import Message from './message'

export default class MessageLinkedList {
  head: Message | null
  tail: Message | null
  length: number
  map: Map<string, Message>
  messageGroups: Map<string, Message[]>
  firstMessageOfDate: Map<number, Message>

  prev: MessageLinkedList | null = null
  next: MessageLinkedList | null = null

  constructor(data: Array<Record<string, unknown>>) {
    this.head = null
    this.tail = null
    this.length = 0
    this.map = new Map()
    this.messageGroups = new Map()
    this.firstMessageOfDate = new Map()
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const extract = (m: any): Message[] => {
      const message = Message.createReactive(m)
      if (message) {
        return [message].concat(extract(m.reply))
      }
      return []
    }
    for (const m of data.reverse()) {
      const message = Message.createReactive(m)
      if (message) {
        this.append(message)
      }
      for (const message of extract(m.reply)) {
        this.map.set(message.id, message)
      }
    }
  }

  append(message: Message) {
    if (this.contains(message.id)) return
    if (this.tail) {
      let current: Message | null = this.tail
      while (current && current.createdAt > message.createdAt) {
        current = current.prev
      }
      if (current) {
        if (current === this.tail) {
          this.tail = message
        }
        message.next = current.next
        current.next = message
        message.prev = current
      } else {
        message.next = this.head
        this.head = message
      }
      if (message.next) {
        message.next.prev = message
      }
    } else {
      this.head = this.tail = message
    }
    this.map.set(message.id, message)
    this.length++
    this.insertMessageToGroup(message)
  }

  insertMessageToGroup(message: Message) {
    const firstMessage = this.firstMessageOfDate.get(message.dateId)
    if (!firstMessage || firstMessage.createdAt > message.createdAt) {
      this.firstMessageOfDate.set(message.dateId, message)
    }
    if (message.isSystem) return
    // if (message.status !== MessageStatus.Delivered) return
    if (this.messageGroups.has(message.groupId)) {
      const group = this.messageGroups.get(message.groupId)
      if (group) {
        let hasInserted = false
        for (let index = group.length - 1; index >= 0; index--) {
          if (group[index].createdAt < message.createdAt) {
            if (index == group.length - 1) {
              group.push(message)
            } else {
              group.splice(index + 1, 0, message)
            }
            hasInserted = true
            break
          }
        }
        if (!hasInserted) {
          group.unshift(message)
        }
      }
    } else {
      this.messageGroups.set(message.groupId, [message])
    }
  }

  remove(id: string) {
    const target = this.finds(id)
    if (!target) return

    if (target.prev) {
      target.prev.next = target.next
    } else {
      this.head = target.next
    }

    if (target.next) {
      target.next.prev = target.prev
    } else {
      this.tail = target.prev
    }

    this.map.delete(id)
    this.length--

    const group = this.messageGroups.get(target.groupId)
    if (group) {
      const index = group.indexOf(target)
      if (index >= 0) {
        group.splice(index, 1)
        if (group.length === 0) {
          this.messageGroups.delete(target.groupId)
        }
      }
    }

    if (this.firstMessageOfDate.get(target.dateId)?.id === target.id) {
      if (target.dateId === target.next?.dateId) {
        this.firstMessageOfDate.set(target.dateId, target.next)
      } else {
        this.firstMessageOfDate.delete(target.dateId)
      }
    }
  }

  replace(id: string, message: Message) {
    const target = this.finds(id)
    if (target) {
      if (target.prev) {
        target.prev.next = message
      } else {
        this.head = message
      }
      if (target.next) {
        target.next.prev = message
      } else {
        this.tail = message
      }
      message.prev = target.prev
      message.next = target.next
      this.map.delete(id)
      this.map.set(message.id, message)
      const group = this.messageGroups.get(target.groupId)
      if (group) {
        const index = group.indexOf(target)
        if (index >= 0) {
          if (message.isSystem) {
            group.splice(index, 1)
          } else {
            group[index] = message
          }
        }
      }
      if (this.firstMessageOfDate.get(target.dateId)?.id === target.id) {
        this.firstMessageOfDate.set(target.dateId, message)
      }
    }
  }

  concate(linkedList: MessageLinkedList) {
    if (linkedList.length === 0) return

    // Strip overlapping messages from linkedList's head (the joining side)
    let effectiveHead = linkedList.head
    let trimmedCount = 0
    while (effectiveHead && this.map.has(effectiveHead.id)) {
      effectiveHead = effectiveHead.next
      trimmedCount++
    }
    if (!effectiveHead) return // all messages overlap
    if (effectiveHead !== linkedList.head) {
      effectiveHead.prev = null
    }

    if (!this.tail) {
      this.head = effectiveHead
      this.tail = linkedList.tail
    } else {
      this.tail.next = effectiveHead
      effectiveHead.prev = this.tail
      this.tail = linkedList.tail
    }
    for (const [key, value] of linkedList.map) {
      if (!this.map.has(key)) {
        this.map.set(key, value)
      }
    }
    this.length += linkedList.length - trimmedCount
    this.mergeMetadata(linkedList)
  }

  unshift(linkedList: MessageLinkedList) {
    if (linkedList.length === 0) return

    // Strip overlapping messages from linkedList's tail (the joining side)
    let effectiveTail = linkedList.tail
    let trimmedCount = 0
    while (effectiveTail && this.map.has(effectiveTail.id)) {
      effectiveTail = effectiveTail.prev
      trimmedCount++
    }
    if (!effectiveTail) return // all messages overlap
    if (effectiveTail !== linkedList.tail) {
      effectiveTail.next = null
    }

    if (!this.head) {
      this.head = linkedList.head
      this.tail = effectiveTail
    } else {
      this.head.prev = effectiveTail
      effectiveTail.next = this.head
      this.head = linkedList.head
    }
    for (const [key, value] of linkedList.map) {
      if (!this.map.has(key)) {
        this.map.set(key, value)
      }
    }
    this.length += linkedList.length - trimmedCount
    this.mergeMetadata(linkedList)
  }

  private mergeMetadata(linkedList: MessageLinkedList) {
    for (const [key, value] of linkedList.messageGroups) {
      if (this.messageGroups.has(key)) {
        const group = this.messageGroups.get(key)
        if (group) {
          for (const message of value) {
            this.insertMessageToGroup(message)
          }
        }
      } else {
        this.messageGroups.set(key, value)
      }
    }
    for (const [key, value] of linkedList.firstMessageOfDate) {
      const firstMessage = this.firstMessageOfDate.get(key)
      if (
        firstMessage === undefined ||
        firstMessage.createdAt > value.createdAt
      ) {
        this.firstMessageOfDate.set(key, value)
      }
    }
  }

  private removeFromMetadata(message: Message) {
    const group = this.messageGroups.get(message.groupId)
    if (group) {
      const idx = group.indexOf(message)
      if (idx >= 0) group.splice(idx, 1)
      if (group.length === 0) this.messageGroups.delete(message.groupId)
    }
    if (this.firstMessageOfDate.get(message.dateId)?.id === message.id) {
      this.firstMessageOfDate.delete(message.dateId)
    }
  }

  resetHead(id: string) {
    if (this.head && this.head.id === id) return
    const target = this.finds(id)
    if (target) {
      // Remove orphaned entries from map and secondary structures
      let orphanCount = 0
      let orphan: Message | null = this.head
      while (orphan && orphan !== target) {
        this.map.delete(orphan.id)
        this.removeFromMetadata(orphan)
        orphan = orphan.next
        orphanCount++
      }
      this.head = target
      target.prev = null
      this.length -= orphanCount
    }
  }

  resetTail(id: string) {
    if (this.tail && this.tail.id === id) return
    const target = this.finds(id)
    if (target) {
      // Remove orphaned entries from map and secondary structures
      let orphanCount = 0
      let orphan: Message | null = this.tail
      while (orphan && orphan !== target) {
        this.map.delete(orphan.id)
        this.removeFromMetadata(orphan)
        orphan = orphan.prev
        orphanCount++
      }
      this.tail = target
      target.next = null
      this.length -= orphanCount
    }
  }

  canCombine(linkedList: MessageLinkedList) {
    if (linkedList.length === 0 || !linkedList.head || !linkedList.tail)
      return false
    return (
      this.contains(linkedList.tail!.id) ||
      this.contains(linkedList.head!.id) ||
      (linkedList.contains(this.head?.id ?? '') &&
        linkedList.contains(this.tail?.id ?? ''))
    )
  }

  combine(linkedList: MessageLinkedList) {
    if (linkedList.length === 0 || !linkedList.head || !linkedList.tail) return
    const containsHead = this.contains(linkedList.head!.id)
    const containsTail = this.contains(linkedList.tail!.id)
    if (containsHead && containsTail) {
      return
    } else if (!containsHead && !containsTail) {
      if (
        linkedList.contains(this.head?.id ?? '') &&
        linkedList.contains(this.tail?.id ?? '')
      ) {
        this.head = linkedList.head
        this.tail = linkedList.tail
        this.length = linkedList.length
        this.map = linkedList.map
      }
    } else if (containsTail) {
      const head = this.finds(linkedList.tail!.id)?.next
      if (head) {
        this.resetHead(head.id)
      } else {
        this.head = null
        this.tail = null
        this.length = 0
        this.map.clear()
        this.messageGroups.clear()
        this.firstMessageOfDate.clear()
      }
      this.unshift(linkedList)
    } else if (containsHead) {
      const tail = this.finds(linkedList.head!.id)?.prev
      if (tail) {
        this.resetTail(tail.id)
      } else {
        this.head = null
        this.tail = null
        this.length = 0
        this.map.clear()
        this.messageGroups.clear()
        this.firstMessageOfDate.clear()
      }
      this.concate(linkedList)
    }
  }

  array() {
    const messages: Message[] = []
    let current = this.head
    while (current) {
      messages.push(current)
      current = current.next
    }
    return messages
  }

  finds(id: string) {
    const found = this.map.get(id)
    if (found) {
      if (found.next || found.prev) {
        return found
      } else {
        return this.head === found && this.tail === found ? found : undefined
      }
    } else {
      return undefined
    }
  }

  contains(id: string) {
    return this.finds(id) !== undefined
  }

  isValid() {
    if (this.head && this.head.prev) {
      return false
    }
    if (this.tail && this.tail.next) {
      return false
    }
    let length = 0
    let current = this.head
    while (current) {
      if (current.prev && current.prev.next !== current) {
        return false
      }
      if (current.next && current.next.prev !== current) {
        return false
      }
      length++
      current = current.next
    }
    return length === this.length
  }
}
