import { useImkitStore } from '../stores/imkit'
export default (
  roomId: string,
  action: {
    type: string
    label: string
    uri: string
    text: string
  }
) => {
  switch (action.type) {
    case 'message': {
      const payload = {
        roomId,
        messageType: 'text',
        message: action.text
      }
      useImkitStore().sendMessage(payload)
      break
    }
    case 'uri':
      window.open(action.uri, '_blank')
      break
    default:
      console.error(`Unsupported action type: ${action.type}`)
      break
  }
}
