<script setup lang="ts">
import { VList } from 'virtua/vue'
import { computed, ref } from 'vue'
import { useVfm, VueFinalModal } from 'vue-final-modal'
import Folder from '../../classes/folder'
import { useImkitStore } from '../../stores/imkit'
import RoomCell from './RoomCell.vue'

const vfm = useVfm()
const props = defineProps<{ folderId: string }>()
const imkit = useImkitStore()
const folder = ref<Folder | undefined>()
const folderName = ref('')
const sortedRooms = computed(() => {
  if (folder.value) {
    return folder.value.roomIds
      .map((id: string) => imkit.rooms[id])
      .concat(imkit.sortedRooms)
      .sort((a, b) =>
        !!a.pref?.sticky === !!b.pref?.sticky
          ? b.updatedAt - a.updatedAt
          : a.pref?.sticky
            ? -1
            : 1
      )
  } else {
    return imkit.sortedRooms
  }
})
const isValid = computed(
  () =>
    folderName.value.length > 0 &&
    Object.keys(imkit.selectedRoomIdsForCreateFolder).length > 0
)

const submit = () => {
  imkit.updateFolder({
    folderKey: folder.value?.id || `folder_${Date.now()}`,
    name: folderName.value
  })
}
folder.value = imkit.folders[props.folderId]
if (folder.value) {
  folderName.value = folder.value.name
  const seedTime = Date.now()
  imkit.$patch({
    selectedRoomIdsForCreateFolder: folder.value.roomIds.reduce(
      (acc: { [roomId: string]: Date }, roomId: string, index: number) => {
        acc[roomId] = new Date(seedTime + index)
        return acc
      },
      {}
    )
  })
}
</script>

<template>
  <vue-final-modal
    class="flex items-center justify-center"
    content-class="bg-white dark:bg-zinc-800 rounded-xl p-5 flex flex-col gap-3 w-[360px]"
    content-transition="vfm-fade"
    overlay-transition="vfm-fade"
  >
    <div
      class="mb-1 flex items-center justify-between text-xl font-medium text-gray-700 dark:text-gray-300"
    >
      {{ folder ? $t('editFolder') : $t('createFolder') }}
    </div>
    <input
      v-model="folderName"
      type="text"
      class="grow rounded-md bg-gray-100 p-2 placeholder-gray-400 outline-none dark:bg-zinc-700"
      :placeholder="$t('folderName')"
    />
    <div class="flex h-[50vh] flex-col">
      <VList
        v-slot="{ item }"
        :data="sortedRooms"
        :item-size="44"
        class="grow overflow-auto"
      >
        <RoomCell :source="item" />
      </VList>
    </div>
    <div class="flex items-center justify-center gap-2">
      <button
        class="disabled:(bg-blue-200 cursor-not-allowed) h-10 grow rounded-lg border border-gray-200 text-base text-gray-800 dark:border-stone-400 dark:text-stone-400"
        @click="
          () => {
            vfm.closeAll()
          }
        "
      >
        {{ $t('cancel') }}
      </button>
      <button
        class="h-10 grow rounded-lg bg-blue-400 text-base text-white"
        :class="{ 'cursor-not-allowed bg-gray-400!': !isValid }"
        :disabled="!isValid"
        @click="
          () => {
            submit()
            vfm.closeAll()
          }
        "
      >
        {{ $t('confirm') }}
      </button>
    </div>
  </vue-final-modal>
</template>
