class User {
  id: string
  nickname: string
  avatarUrl: string
  country: string | null
  city: string | null
  clientType: string | null
  memberIds: { [id: string]: boolean }

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  constructor(raw: any) {
    const {
      _id: id,
      nickname,
      avatarUrl,
      country,
      city,
      clientType,
      members
    } = raw
    this.id = id
    this.nickname = nickname ?? id
    this.avatarUrl = avatarUrl
    this.country = country ?? null
    this.city = city ?? null
    this.clientType = clientType ?? null
    this.memberIds = {}
    members?.forEach((m: { _id: string }) => {
      this.memberIds[m._id] = true
    })
  }
}
export default User
