<script setup lang="ts">
import { File } from 'lucide-vue-next'
import { computed, ref } from 'vue'
import { useModal } from 'vue-final-modal'
import { useI18n } from 'vue-i18n'
import IMImage from '../classes/image'
import { getConfig } from '../runtime/config'
import { useImkitStore } from '../stores/imkit'
import Message, {
  FileMessage,
  ImageMessage,
  MessageType,
  MixedMessage,
  TextMessage
} from './../classes/message'
import AvatarModal from './AvatarModal.vue'
import AvatarView from './AvatarView.vue'
import MediaImg from './ui/MediaImg.vue'

// Custom function to highlight keywords in rendered HTML
const highlightKeywords = (html: string, keyword: string): string => {
  if (!keyword) return html

  const escapedKeyword = escapeRegExp(keyword)
  const regex = new RegExp(
    `(?<![a-zA-Z0-9_])${escapedKeyword}(?![a-zA-Z0-9_])`,
    'uig'
  )

  // Only highlight text content, not within HTML tags
  // Use [\s\S] instead of . to match across newlines from <br>\n
  return html.replace(/>([\s\S]*?)</g, (match, textContent) => {
    const highlighted = textContent.replace(regex, (match: string) => {
      return `<span class="bg-amber-400 text-white">${match}</span>`
    })
    return `>${highlighted}<`
  })
}
const props = defineProps<{ message: TextMessage }>()
const imkit = useImkitStore()
const config = getConfig()
const replyMessage = computed((): Message | undefined => {
  if (!props.message.replyId) return undefined
  return imkit.messageMultiLists
    .get(imkit.selectedRoomId)
    ?.main?.map.get(props.message.replyId)
})
const replyMessageSender = computed(() => {
  const reply = replyMessage.value
  if (!reply) return null
  return imkit.users[reply.senderId]
})
const isIncoming = computed(() => props.message.isIncoming)
const linkPreviews = computed(() => {
  if (!config.settings.linkPreviewEnabled) return []
  const { urls } = props.message
  if (!urls) return []
  return urls.map((url) => imkit.linkPreviews[url]).filter((l) => l)
})
const loadingLinkPreviewUrls = computed(() => {
  if (!config.settings.linkPreviewEnabled) return []
  const { urls } = props.message
  if (!urls) return []
  const loadingSet = imkit.loadingLinkPreviews as Set<string>
  return urls.filter((url) => loadingSet.has(url) && !imkit.linkPreviews[url])
})
const description = computed((): string => {
  if (!replyMessage.value) return ''
  if (replyMessage.value.type === MessageType.Text) {
    return (replyMessage.value as TextMessage).string
  } else if (replyMessage.value.type === MessageType.Mixed) {
    return (replyMessage.value as MixedMessage).string
  } else if (replyMessage.value.type === MessageType.File) {
    const file = replyMessage.value as FileMessage
    return `${file.fileName}.${file.fileExtension}`
  } else if (
    replyMessage.value.type === MessageType.Image ||
    replyMessage.value.type === MessageType.Video ||
    replyMessage.value.type === MessageType.Sticker
  ) {
    const { t } = useI18n()
    const messageTypeName = {
      [MessageType.Image]: t('image'),
      [MessageType.Video]: t('video'),
      [MessageType.Sticker]: t('sticker')
    }
    return messageTypeName[replyMessage.value.type]
  }
  return ''
})
const image = computed((): IMImage | undefined => {
  if (replyMessage.value?.type === MessageType.Image) {
    return (replyMessage.value as ImageMessage).images[0]
  }
  if (replyMessage.value?.type === MessageType.Mixed) {
    return (replyMessage.value as MixedMessage).images[0]
  }
  return undefined
})
const failedLinkPreviewImages = ref(new Set<string>())
const handleLinkPreviewImageError = (url: string) => {
  failedLinkPreviewImages.value = new Set([
    ...failedLinkPreviewImages.value,
    url
  ])
}
const handleMentionClick = (event: MouseEvent) => {
  const target = event.target as HTMLElement
  if (target.tagName === 'SPAN' && target.dataset.uid) {
    const user = imkit.users[target.dataset.uid]
    if (!user) return
    const { open } = useModal({
      component: AvatarModal,
      attrs: {
        url: user.avatarUrl ?? '',
        name: user.nickname ?? ''
      }
    })
    open()
  }
}

function escapeRegExp(string: string): string {
  // $& means the whole matched string
  return string.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&')
}

const html = computed((): string => {
  const keyword = imkit.messageSearchKeyword
  return highlightKeywords(props.message.html, keyword)
})
const handleLinkPreviewClick = (url: string) => {
  window.open(url, '_blank')
}
const handleCopy = (event: ClipboardEvent) => {
  const selection = window.getSelection()
  const selectedText = selection?.toString()
  if (selectedText) {
    // User selected specific text, let the browser handle the copy natively
    return
  }
  // No selection, copy the entire message text
  event.preventDefault()
  event.clipboardData?.setData('text/plain', props.message.text)
}
const navigate = () => {
  if (!props.message.replyId) return
  imkit.navigateToMessage(props.message.replyId)
}
</script>

<template>
  <div v-if="replyMessage" class="flex flex-col gap-2">
    <div
      data-testid="message-quoted"
      class="flex cursor-pointer items-center gap-3"
      @click="navigate"
    >
      <avatar-view
        class="row-span-2 h-7 w-7 shrink-0 rounded-lg text-base"
        :url="replyMessageSender?.avatarUrl ?? ''"
        :name="replyMessageSender?.nickname ?? ''"
      />
      <div class="flex flex-col gap-1">
        <div class="text-base font-bold text-gray-600 dark:text-gray-300">
          {{ replyMessageSender?.nickname }}
        </div>
        <div
          class="multiline-ellipsis text-xs break-all text-gray-500 dark:text-gray-300"
        >
          {{ description }}
        </div>
      </div>
      <MediaImg
        v-if="image"
        :url="image.thumbnailUrl"
        kind="image"
        no-callout
        img-class="ml-auto h-10 w-10 rounded-sm object-cover"
      />
      <File
        v-if="replyMessage.type === MessageType.File"
        :size="28"
        class="ml-auto text-gray-500 dark:text-gray-300"
      />
    </div>
    <div class="-mx-4 h-px bg-gray-200 dark:bg-zinc-600" />
    <div
      class="prose max-w-none wrap-break-word select-none dark:prose-invert pointer-fine:select-text"
      @click="handleMentionClick"
      @copy="handleCopy"
      v-html="html"
    />
  </div>
  <div
    v-else
    class="prose max-w-none wrap-break-word select-none dark:prose-invert pointer-fine:select-text prose-p:leading-5.5 prose-ol:my-0"
    @click="handleMentionClick"
    @copy="handleCopy"
    v-html="html"
  />
  <div
    v-if="isIncoming && message.translatedText"
    dir="auto"
    class="mt-1 break-words text-gray-400"
  >
    {{ $t('translation') }}: {{ message.translatedText }}
  </div>
  <div
    v-if="linkPreviews.length > 0 || loadingLinkPreviewUrls.length > 0"
    class="my-1 flex flex-col gap-3"
  >
    <!-- Skeleton loaders for loading link previews -->
    <div
      v-for="url in loadingLinkPreviewUrls"
      :key="url"
      class="flex animate-pulse items-stretch justify-center gap-2"
    >
      <div class="my-0.5 w-0.5 shrink-0 rounded-full bg-gray-300" />
      <div
        class="align-center flex grow flex-col justify-center gap-1.5 overflow-hidden"
      >
        <div class="h-4 w-3/4 rounded bg-gray-200 dark:bg-zinc-600" />
        <div class="h-3 w-1/2 rounded bg-gray-200 dark:bg-zinc-600" />
      </div>
      <div
        class="my-auto h-12 w-12 shrink-0 rounded-sm bg-gray-200 dark:bg-zinc-600"
      />
    </div>
    <!-- Loaded link previews -->
    <div
      v-for="linkPreview in linkPreviews"
      :key="linkPreview.url"
      data-testid="link-preview-card"
      class="flex cursor-pointer items-stretch justify-center gap-2"
      @click="handleLinkPreviewClick(linkPreview.url)"
    >
      <div class="my-0.5 w-0.5 shrink-0 rounded-full bg-blue-300" />
      <div
        class="align-center flex grow flex-col justify-center gap-0.5 overflow-hidden"
      >
        <div class="ellipsis text-base font-bold">
          {{ linkPreview.title }}
        </div>
        <div class="multiline-ellipsis text-xs">
          {{ linkPreview.description || $t('tapOpen') }}
        </div>
      </div>
      <img
        v-if="
          linkPreview.images.length > 0 &&
          !failedLinkPreviewImages.has(linkPreview.url)
        "
        :src="linkPreview.images[0]"
        alt=""
        class="my-auto h-12 w-12 shrink-0 rounded-sm object-cover"
        @error="handleLinkPreviewImageError(linkPreview.url)"
      />
      <div
        v-else-if="failedLinkPreviewImages.has(linkPreview.url)"
        data-testid="link-preview-image-placeholder"
        aria-hidden="true"
        class="my-auto h-12 w-12 shrink-0 rounded-sm bg-gray-100 dark:bg-zinc-700"
      />
    </div>
  </div>
</template>
