  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  overflow: hidden;
}
.ellipsis {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 1;
  overflow: hidden;
}

:deep(a) {
  color: #3b82f6;
  text-decoration: underline;
  word-break: break-all;
}
:global(.dark) :deep(a) {
  color: #60a5fa;
}
:deep(code:not(pre code) a) {
  color: inherit;
  text-decoration: none;
}
:global(.dark) :deep(code:not(pre code) a) {
  color: inherit;
}

:deep(p:first-child:last-child) {
  margin-bottom: 0;
}

:deep(li) {
  margin-top: 0;
  margin-bottom: 0;
}
:deep(ol > li)::marker,
:deep(ul > li)::marker {
  color: inherit;
}

/* Remove backticks added by Tailwind Typography prose */
:deep(code)::before,
:deep(code)::after {
  content: none;
}

/* GitHub-style inline code (exclude code blocks inside <pre>) */
:deep(code:not(pre code)) {
  display: inline;
  padding: 0.15em 0.3em;
  border-radius: 6px;
  background-color: rgba(175, 184, 193, 0.2);
  font-size: 85%;
  line-height: inherit;
  white-space: break-spaces;
  word-wrap: break-word;
  vertical-align: bottom;
}
