/* eslint-disable vue/one-component-per-file */
import { X } from 'lucide-vue-next'
import {
  DialogClose as DialogClosePrimitive,
  DialogContent as DialogContentPrimitive,
  DialogDescription as DialogDescriptionPrimitive,
  DialogOverlay as DialogOverlayPrimitive,
  DialogPortal,
  DialogRoot,
  DialogTitle as DialogTitlePrimitive,
  DialogTrigger
} from 'radix-vue'
import type { HTMLAttributes } from 'vue'
import { defineComponent, h } from 'vue'
import { cn, type ClassValue } from '../../utils/cn'

const Dialog = DialogRoot

const DialogTriggerComponent = DialogTrigger

const DialogPortalComponent = DialogPortal

const DialogClose = DialogClosePrimitive

const DialogOverlay = defineComponent({
  name: 'DialogOverlay',
  inheritAttrs: false,
  props: {
    class: {
      type: null,
      default: undefined
    }
  },
  setup(props, { slots, attrs }) {
    return () => {
      const overlayAttrs = { ...attrs } as Record<string, unknown>
      const className = overlayAttrs.class as ClassValue
      delete overlayAttrs.class

      return h(
        DialogOverlayPrimitive,
        {
          ...overlayAttrs,
          class: cn(
            'data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 fixed inset-0 z-50 bg-black/40',
            className,
            props.class as ClassValue
          )
        },
        slots
      )
    }
  }
})

const DialogContent = defineComponent({
  name: 'DialogContent',
  inheritAttrs: false,
  props: {
    class: {
      type: null,
      default: undefined
    },
    hideClose: {
      type: Boolean,
      default: false
    }
  },
  setup(props, { slots, attrs }) {
    return () => {
      const contentAttrs = { ...attrs } as Record<string, unknown>
      const className = contentAttrs.class as ClassValue
      delete contentAttrs.class

      return h(DialogPortalComponent, null, {
        default: () => [
          h(DialogOverlay),
          h(
            DialogContentPrimitive,
            {
              ...contentAttrs,
              class: cn(
                'max-w-[90vw] rounded-xl bg-background data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 data-[state=closed]:zoom-out-95 data-[state=open]:zoom-in-95 data-[state=closed]:slide-out-to-left-1/2 data-[state=closed]:slide-out-to-top-[48%] data-[state=open]:slide-in-from-left-1/2 data-[state=open]:slide-in-from-top-[48%] fixed top-[50%] left-[50%] z-50 grid w-full translate-x-[-50%] translate-y-[-50%] gap-4 p-6 shadow-lg duration-200 sm:rounded-lg',
                className,
                props.class as ClassValue
              )
            },
            {
              default: () => [
                slots.default?.(),
                !props.hideClose
                  ? h(
                      DialogClose,
                      {
                        class:
                          'ring-offset-background data-[state=open]:bg-accent data-[state=open]:text-muted-foreground focus:ring-ring absolute top-4 right-4 rounded-sm opacity-70 transition-opacity hover:opacity-100 focus:outline-none focus:ring-2 focus:ring-offset-2 disabled:pointer-events-none'
                      },
                      {
                        default: () => [
                          h(X, { class: 'h-4 w-4' }),
                          h('span', { class: 'sr-only' }, 'Close')
                        ]
                      }
                    )
                  : null
              ]
            }
          )
        ]
      })
    }
  }
})

const DialogHeader = defineComponent({
  name: 'DialogHeader',
  inheritAttrs: false,
  props: {
    class: {
      type: null,
      default: undefined
    }
  },
  setup(props, { slots, attrs }) {
    return () => {
      const headerAttrs = { ...attrs } as HTMLAttributes
      const className = headerAttrs.class as ClassValue
      delete headerAttrs.class

      return h(
        'div',
        {
          ...headerAttrs,
          class: cn(
            'flex flex-col space-y-1.5 text-center sm:text-left',
            className,
            props.class as ClassValue
          )
        },
        slots
      )
    }
  }
})

const DialogFooter = defineComponent({
  name: 'DialogFooter',
  inheritAttrs: false,
  props: {
    class: {
      type: null,
      default: undefined
    }
  },
  setup(props, { slots, attrs }) {
    return () => {
      const footerAttrs = { ...attrs } as HTMLAttributes
      const className = footerAttrs.class as ClassValue
      delete footerAttrs.class

      return h(
        'div',
        {
          ...footerAttrs,
          class: cn(
            'flex flex-col-reverse sm:flex-row sm:justify-end sm:space-x-2',
            className,
            props.class as ClassValue
          )
        },
        slots
      )
    }
  }
})

const DialogTitle = defineComponent({
  name: 'DialogTitle',
  inheritAttrs: false,
  props: {
    class: {
      type: null,
      default: undefined
    }
  },
  setup(props, { slots, attrs }) {
    return () => {
      const titleAttrs = { ...attrs } as Record<string, unknown>
      const className = titleAttrs.class as ClassValue
      delete titleAttrs.class

      return h(
        DialogTitlePrimitive,
        {
          ...titleAttrs,
          class: cn(
            'text-xl leading-none font-semibold tracking-tight',
            className,
            props.class as ClassValue
          )
        },
        slots
      )
    }
  }
})

const DialogDescription = defineComponent({
  name: 'DialogDescription',
  inheritAttrs: false,
  props: {
    class: {
      type: null,
      default: undefined
    }
  },
  setup(props, { slots, attrs }) {
    return () => {
      const descriptionAttrs = { ...attrs } as Record<string, unknown>
      const className = descriptionAttrs.class as ClassValue
      delete descriptionAttrs.class

      return h(
        DialogDescriptionPrimitive,
        {
          ...descriptionAttrs,
          class: cn(
            'text-muted-foreground text-base',
            className,
            props.class as ClassValue
          )
        },
        slots
      )
    }
  }
})

export {
  Dialog,
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogOverlay,
  DialogPortalComponent as DialogPortal,
  DialogTitle,
  DialogTriggerComponent as DialogTrigger
}
