<script setup lang="ts">
import { Info, Pencil, X } from 'lucide-vue-next'
import { computed, ref } from 'vue'
import { useVfm, VueFinalModal } from 'vue-final-modal'
import { useImkitStore } from '../stores/imkit'

const PRESET_COLORS: Record<string, string> = {
  red: '#ef4444',
  orange: '#f97316',
  yellow: '#eab308',
  green: '#22c55e',
  blue: '#3b82f6',
  purple: '#a855f7',
  pink: '#ec4899',
  gray: '#6b7280'
}

const MODES = {
  ADD: 'add',
  EDIT: 'edit'
}

const vfm = useVfm()
const props = defineProps<{ roomId: string }>()
const imkit = useImkitStore()
const tags = ref<string[]>([])
const tagColors = ref<{ [tag: string]: string }>({})
const tag = ref('')
const color = ref(PRESET_COLORS.red)
const currentMode = ref(MODES.ADD)
const editingTag = ref('')
const customHexColor = ref('')

const isDuplicatedTag = computed(() => {
  if (!tag.value.trim()) {
    return false
  }

  if (currentMode.value === MODES.EDIT && tag.value === editingTag.value) {
    return false
  }

  const isTagExists = tags.value.includes(tag.value)
  return isTagExists
})
const isInAddMode = computed(() => currentMode.value === MODES.ADD)

const isValidHex = (hex: string): boolean => {
  return /^#([0-9A-Fa-f]{3}){1,2}$/.test(hex)
}

const confirm = (roomId: string) => {
  imkit.updateRoomPrefs({
    roomId,
    prefs: {
      tags: tags.value,
      tagColors: tagColors.value
    }
  })
}
const room = imkit.rooms[props.roomId]
if (room.pref) {
  tags.value = [...(room.pref.tags || [])]
  tagColors.value = { ...(room.pref.tagColors || {}) }
}
const add = () => {
  if (!tag.value) return
  if (!isValidHex(color.value)) return

  if (currentMode.value === MODES.EDIT) {
    const oldTag = editingTag.value
    tags.value = tags.value.filter((t) => t !== oldTag)
    delete tagColors.value[oldTag]

    if (!tags.value.includes(tag.value)) {
      tags.value.push(tag.value)
    }
    tagColors.value[tag.value] = color.value

    currentMode.value = MODES.ADD
    editingTag.value = ''
  } else {
    if (tags.value.length >= 5) {
      return
    }
    if (!tags.value.includes(tag.value)) {
      tags.value.push(tag.value)
    }
    tagColors.value[tag.value] = color.value
  }

  tag.value = ''
  color.value = PRESET_COLORS.red
  customHexColor.value = ''
  confirm(props.roomId)
}

const onClickEditTag = (editTag: string) => {
  currentMode.value = MODES.EDIT
  editingTag.value = editTag
  tag.value = editTag
  const tagColor = tagColors.value[editTag]
  color.value = tagColor

  const isPresetColor = Object.values(PRESET_COLORS).includes(tagColor)
  customHexColor.value = isPresetColor ? '' : tagColor
}

const cancelEdit = () => {
  currentMode.value = MODES.ADD
  editingTag.value = ''
  tag.value = ''
  color.value = PRESET_COLORS.red
  customHexColor.value = ''
}

const onClickRemoveTag = (deleteTag: string) => {
  tags.value = tags.value.filter((t) => t !== deleteTag)
  delete tagColors.value[deleteTag]
  confirm(props.roomId)
}

const onClickSelectTag = (selectedTag: string) => {
  tag.value = selectedTag
  color.value = tagColors.value[selectedTag]
}
</script>

<template>
  <vue-final-modal
    class="flex items-center justify-center"
    content-class="bg-white dark:bg-[#0f1729] rounded-xl p-5 flex flex-col gap-3 max-w-[360px] w-full"
    content-transition="vfm-fade"
    overlay-transition="vfm-fade"
  >
    <div
      class="mb-1 mb-5 flex w-full items-center justify-between text-xl font-semibold text-gray-900 dark:text-white"
    >
      <p>
        {{ isInAddMode ? $t('manageTag') : $t('editTag') }}
      </p>
      <button class="flex items-center justify-center" @click="vfm.closeAll()">
        <X class="h-6 w-6" />
      </button>
    </div>
    <div v-if="tags.length > 0 && isInAddMode">
      <label
        class="mb-2 block text-base font-medium text-gray-900 dark:text-white"
        >{{ $t('currentTags') }} ({{ tags.length }}/5)</label
      >
      <div class="flex flex-wrap gap-2">
        <div
          v-for="tg in tags"
          :key="tg"
          class="focus:ring-ring bg-secondary text-secondary-foreground hover:bg-secondary/80 flex items-center gap-1 rounded-full border border-transparent px-2 py-1 text-xs font-semibold transition-colors focus:ring-2 focus:ring-offset-2 focus:outline-none"
          :style="{
            backgroundColor: `${tagColors[tg]}20`,
            color: tagColors[tg],
            borderColor: `${tagColors[tg]}40`
          }"
          @click="onClickSelectTag(tg)"
        >
          {{ tg }}
          <button
            class="ml-1 cursor-pointer hover:opacity-70"
            @click.stop="onClickEditTag(tg)"
          >
            <Pencil class="h-3 w-3" />
          </button>
          <button
            class="cursor-pointer hover:opacity-70"
            @click.stop="onClickRemoveTag(tg)"
          >
            <X class="h-3 w-3" />
          </button>
        </div>
      </div>
    </div>
    <div>
      <label
        class="mb-2 block text-base font-medium text-gray-900 dark:text-white"
      >
        {{ isInAddMode ? $t('createTag') : $t('editTag') }}
      </label>
      <input
        v-model="tag"
        type="text"
        :class="[
          'w-full grow rounded-md border border-[#222f44] p-2 text-base text-gray-900 placeholder-gray-400 outline-none dark:text-gray-200 dark:placeholder-gray-400',
          isDuplicatedTag && 'border-red-500'
        ]"
        :placeholder="isInAddMode ? $t('createTag') : $t('editTag')"
        :disabled="tags.length >= 5 && isInAddMode"
      />
    </div>
    <div v-if="tags.length < 5 || !isInAddMode" class="mt-3">
      <label
        class="mb-2 block text-base font-medium text-gray-900 dark:text-white"
        >{{ $t('chooseColor') }}</label
      >
      <div class="flex gap-2">
        <button
          v-for="c in Object.keys(PRESET_COLORS)"
          :key="c"
          class="h-6 w-6 rounded-full border-2 transition-all"
          :class="
            color === PRESET_COLORS[c]
              ? 'border-foreground scale-110'
              : 'border-border'
          "
          :style="{ backgroundColor: PRESET_COLORS[c] }"
          @click="color = PRESET_COLORS[c]"
        />
      </div>
    </div>
    <div v-if="tags.length < 5 || !isInAddMode">
      <div class="mt-3 flex items-center gap-2">
        <button
          class="h-6 w-6 flex-shrink-0 rounded-full border-2 transition-all"
          :class="[
            'flex-shrink-0 rounded-full border-2 transition-all',
            color === customHexColor
              ? 'border-foreground scale-110'
              : 'border-gray-300'
          ]"
          :style="
            customHexColor && isValidHex(customHexColor)
              ? { backgroundColor: customHexColor }
              : {
                  background:
                    'linear-gradient(135deg, #ef4444, #22c55e, #3b82f6)'
                }
          "
          @click="color = customHexColor"
        />
        <input
          v-model="customHexColor"
          type="text"
          placeholder="#000000"
          class="h-8 w-24 rounded-md border border-[#222f44] px-2 font-mono text-base text-gray-900 placeholder-gray-400 outline-none dark:text-gray-200 dark:placeholder-gray-400"
          maxlength="7"
        />
        <span
          v-if="customHexColor && !isValidHex(customHexColor)"
          class="text-xs text-red-500"
        >
          {{ $t('fomatInvalid') }}
        </span>
      </div>
    </div>
    <p
      v-if="tags.length >= 5 && isInAddMode"
      class="flex text-xs text-amber-500"
    >
      <Info class="mr-1 h-4 w-4" />
      {{ $t('tagLimitReached') }}
    </p>
    <div class="flex items-center justify-end gap-2">
      <button
        class="ring-offset-background focus-visible:ring-ring border-input bg-background hover:bg-accent inline-flex h-10 items-center justify-center gap-2 rounded-md border px-4 py-2 text-base leading-none font-medium whitespace-nowrap text-gray-900 transition-colors focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:outline-none disabled:pointer-events-none disabled:opacity-50 dark:text-white [&_svg]:pointer-events-none [&_svg]:shrink-0"
        @click="isInAddMode ? vfm.closeAll() : cancelEdit()"
      >
        {{ $t('close') }}
      </button>
      <button
        class="ring-offset-background focus-visible:ring-ring inline-flex h-10 items-center justify-center gap-2 rounded-md bg-[#2e5ee6] px-4 py-2 text-base leading-none font-medium whitespace-nowrap text-white transition-colors hover:bg-[#2652c7] focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:outline-none disabled:pointer-events-none disabled:opacity-50 [&_svg]:pointer-events-none [&_svg]:shrink-0"
        :class="{ 'cursor-not-allowed': !tag || isDuplicatedTag }"
        :disabled="!tag || isDuplicatedTag"
        @click="add"
      >
        {{ isInAddMode ? $t('add') : $t('save') }}
      </button>
    </div>
  </vue-final-modal>
</template>
