<script setup lang="ts">
defineOptions({ inheritAttrs: false })
import { Virtualizer } from 'virtua/vue'
import {
  computed,
  defineComponent,
  h,
  nextTick,
  onMounted,
  reactive,
  ref,
  watch,
  type PropType
} from 'vue'
import { useImkitStore } from '../stores/imkit'
import AvatarView from './AvatarView.vue'
import MessageCell from './MessageCell.vue'
import StickerPanel from './StickerPanel.vue'
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore
import { vOnClickOutside } from '@vueuse/components'
import dayjs, { Dayjs } from 'dayjs'
import {
  ChevronLeft,
  Info,
  Loader2,
  LogOut,
  MapPin,
  Mic,
  Paperclip,
  Play,
  Plus,
  Search,
  Send,
  Smile,
  X
} from 'lucide-vue-next'
import { Switch, isDark } from 'vue-dark-switch'
import { useModal } from 'vue-final-modal'
import EmojiPicker from 'vue3-emoji-picker'
import 'vue3-emoji-picker/css'
import Message, {
  MessageType,
  MixedMessage,
  TextMessage
} from '../classes/message'
import { RoomType } from '../classes/room'
import Settings from '../classes/settings'
import Styles from '../classes/styles'
import { useAttachmentUpload } from '../composables/useAttachmentUpload'
import { useComposer } from '../composables/useComposer'
import { useMessageListState } from '../composables/useMessageListState'
import { getConfig } from '../runtime/config'
import { getSocket } from '../runtime/socket'
import { getUid } from '../runtime/uid'
import { escapeHtml } from '../utils/escapeHtml'
import fetchParams from '../utils/url'
import At from './at/At.vue'
import AudioInput from './AudioInput.vue'
import EditMessagePreview from './EditMessagePreview.vue'
import EndChatModal from './EndChatModal.vue'
import FileSizeLimitModal from './FileSizeLimitModal.vue'
import LocationModal from './LocationModal.vue'
import ReplyMessagePreview from './ReplyMessagePreview.vue'
import SearchPanel from './SearchPanel.vue'
import StickerSvg from './svgs/StickerSvg.vue'
import TextFormatMenu from './TextFormatMenu.vue'
import ContentLightboxDialog from './ui/ContentLightboxDialog.vue'
import VersionModal from './VersionModal.vue'

const MessageListCell = defineComponent({
  name: 'MessageListCell',
  props: {
    source: {
      type: Object as PropType<Message>,
      required: true
    }
  },
  emits: ['popover:open', 'popover:close'],
  setup(props, { emit }) {
    const onPopoverOpen = (id: string) => emit('popover:open', id)
    const onPopoverClose = (id: string) => emit('popover:close', id)
    return () => {
      const cellProps = {
        source: props.source,
        'onPopover:open': onPopoverOpen,
        'onPopover:close': onPopoverClose
      }
      return props.source.type === MessageType.Typing
        ? h('div', { 'data-testid': 'typing-indicator' }, [
            h(MessageCell, cellProps)
          ])
        : h(MessageCell, cellProps)
    }
  }
})

const imkit = useImkitStore()
const config = getConfig()

const { open } = useModal({
  component: LocationModal
})
const openFileSizeLimitModal = () => {
  const { open } = useModal({
    component: FileSizeLimitModal,
    attrs: {
      fileSizeLimit: fileSizeLimit.value
    }
  })
  open()
}
const openEndChatModal = () => {
  const { open } = useModal({
    component: EndChatModal
  })
  open()
}
const room = computed(() => imkit.rooms[imkit.selectedRoomId])
const selectedRoomId = computed(() => imkit.selectedRoomId)
const hasFixedRoomId = computed(() => {
  return fetchParams().has('roomId')
})

const emojiTheme = computed(() => {
  return isDark.value ? 'dark' : 'light'
})

const isRoomInfoVisible = computed(() => imkit.isRoomInfoVisible)

const fileInput = ref<HTMLInputElement>()
const input = ref<HTMLDivElement>()
const lastTypingDate = ref<Dayjs>(dayjs().subtract(5, 'second'))
const showActions = ref(false)
const formatMenu = ref<InstanceType<typeof TextFormatMenu>>()
const replyId = computed((): string => imkit.replyId)
const editingMessageId = computed((): string => imkit.editingMessageId)
const settings = computed((): Settings => config.settings)
type InputAction = {
  key: string
  icon: typeof Paperclip | typeof MapPin | typeof Mic
  iconClass: string
  label: string
  onClick: () => void
}
const fileSizeLimit = computed(
  () => settings.value.fileUploadSizeLimit ?? 100000000
)
const {
  images,
  imageFiles,
  videos,
  videoFiles,
  isLoadingFiles,
  isLoadingVideo,
  showImageLightbox,
  selectedImageIndex,
  showVideoLightbox,
  selectedVideoUrl,
  onFileChange,
  onDrop,
  onPaste,
  removeImageAtIndex,
  removeVideoAtIndex,
  openImageLightbox,
  openVideoLightbox,
  handleVideoLightboxOpenChange,
  previousImage,
  nextImage
} = useAttachmentUpload({
  roomId: computed(() => room.value?.id ?? ''),
  users: computed(() => imkit.users),
  fileSizeLimit,
  fileInput,
  onOversize: openFileSizeLimitModal,
  sendFile: (payload) => imkit.sendMessage(payload),
  fetchPresignedUrlByPath: (path) => imkit.fetchPresignedUrlByPath(path)
})
const isSearchInRoomMode = computed(() => imkit.isSearchInRoomMode)
const styles = computed((): Styles => config.styles)
const isMobile = computed(() => {
  if (typeof window === 'undefined') return false
  return !window.matchMedia('(hover: hover) and (pointer: fine)').matches
})
const {
  message,
  showStickerPanel,
  showEmojiPicker,
  stickerButtonEl,
  emojiButtonEl,
  showAudioInput,
  send,
  onSelectEmoji,
  onClickOutsideSticker,
  onClickOutsideEmoji,
  toggleStickerPanel,
  toggleEmojiPicker,
  handleImageButtonTapped,
  onCompositionstart,
  onCompositionend,
  onKeydownEnter,
  onBeforeInput,
  onInput,
  onFormatApplied,
  ensureCaretAnchor
} = useComposer({
  room,
  users: computed(() => imkit.users),
  settings,
  isMobile,
  input,
  fileInput,
  images,
  imageFiles,
  videos,
  videoFiles,
  replyId,
  editingMessageId,
  sendMessage: (payload) => imkit.sendMessage(payload),
  editMessage: (payload) => imkit.editMessage(payload),
  clearReply: () => imkit.$patch({ replyId: '' }),
  clearEditing: () => imkit.$patch({ editingMessageId: '' })
})
const scrollEl = ref<HTMLElement | null>(null)
const headerEl = ref<HTMLElement | null>(null)
const headerH = ref(0)

watch(
  () => headerEl.value?.offsetHeight ?? 0,
  (h) => {
    headerH.value = h
  },
  { flush: 'post' }
)

// Popover pinning — lifted state so virtua's :keep-mounted can survive
// MessageCell recycles. MessageCell emits popover:open/close(id).
const openPopoverIds = reactive(new Set<string>())
const {
  isInitialLoaded,
  isLatestMessageVisible,
  isNearBottom,
  isPrepending,
  isRequesting,
  onVlScroll,
  reloadData,
  scrollToBottom,
  setVl,
  sortedMessages
} = useMessageListState({ room, scrollEl })
const keepMountedIndices = computed(() =>
  sortedMessages.value
    .map((msg, index) => (openPopoverIds.has(msg.id) ? index : -1))
    .filter((i) => i >= 0)
)
const inputActions = computed((): InputAction[] => {
  const actions: InputAction[] = []
  if (settings.value.fileInputEnabled) {
    actions.push({
      key: 'file',
      icon: Paperclip,
      iconClass: 'h-6 w-6 text-slate-500 dark:text-slate-400',
      label: 'file',
      onClick: () => {
        showActions.value = false
        handleImageButtonTapped()
      }
    })
  }
  if (settings.value.locationInputEnabled) {
    actions.push({
      key: 'location',
      icon: MapPin,
      iconClass: 'h-6 w-6 text-slate-500 dark:text-slate-400',
      label: 'location',
      onClick: () => {
        showActions.value = false
        open()
      }
    })
  }
  if (settings.value.audioInputEnabled) {
    actions.push({
      key: 'audio',
      icon: Mic,
      iconClass: 'h-6 w-6 text-slate-500 dark:text-slate-400',
      label: 'audio',
      onClick: () => {
        showActions.value = false
        showAudioInput.value = true
      }
    })
  }
  return actions
})
const checkIfDroppable = (event: Event) => {
  event.preventDefault()
}
const back = () => {
  imkit.$patch({ selectedRoomId: '' })
}
const search = () => {
  imkit.$patch({
    isSearchInRoomMode: true
  })
}
onMounted(() => {
  watch(
    selectedRoomId,
    async (newSelectedRoomId, oldSelectedRoomId) => {
      if (newSelectedRoomId === oldSelectedRoomId) return
      if (newSelectedRoomId) {
        if (input.value) {
          input.value.textContent = ''
        }
        message.value = ''
        images.value = []
        imageFiles.value = []
        videos.value = []
        videoFiles.value = []
        await reloadData(newSelectedRoomId)
        if (!isMobile.value) input.value?.focus()
      }
    },
    { immediate: true }
  )
  watch(
    replyId,
    () => {
      if (replyId.value) {
        showAudioInput.value = false
        const wasAtBottom = isNearBottom()
        // Focus synchronously to keep mobile keyboard activation within the user gesture call stack
        if (input.value) {
          input.value.focus()
        } else {
          nextTick(() => input.value?.focus())
        }
        if (wasAtBottom) {
          nextTick(() => scrollToBottom())
        }
      }
    },
    { flush: 'sync' }
  )
  watch(editingMessageId, (newId) => {
    if (newId) {
      imkit.$patch({ replyId: '' })
      showAudioInput.value = false
      showStickerPanel.value = false
      showActions.value = false
      // Focus synchronously so iOS opens the keyboard within the user gesture.
      input.value?.focus()
      const editingMessage = imkit.messageMultiLists
        .get(imkit.selectedRoomId)
        ?.main?.map.get(newId)
      if (
        editingMessage &&
        (editingMessage instanceof TextMessage ||
          editingMessage instanceof MixedMessage)
      ) {
        setTimeout(() => {
          if (input.value) {
            let html = escapeHtml(editingMessage.text)
            html = html.replace(/(\s)?@([\w-]+)/g, (match, _ws, userId) => {
              const user = imkit.users[userId]
              if (user) {
                const safeNickname = escapeHtml(user.nickname)
                return `<span data-at-embedded="" contenteditable="false"> @${safeNickname} </span>`
              }
              return match
            })
            html = html.replace(/\n/g, '<br>')
            input.value.innerHTML = html
            message.value = editingMessage.text
            input.value.focus()
            const range = document.createRange()
            const sel = window.getSelection()
            range.selectNodeContents(input.value)
            range.collapse(false)
            sel?.removeAllRanges()
            sel?.addRange(range)
            // WebKit needs an editable text node when the input only has
            // contenteditable="false" children, otherwise the caret jumps to
            // the far right on click.
            ensureCaretAnchor()
          }
        }, 0)
      }
    } else {
      if (input.value) {
        input.value.textContent = ''
        message.value = ''
      }
    }
  })
  watch(message, () => {
    if (lastTypingDate.value.add(5, 'second') > dayjs()) return
    lastTypingDate.value = dayjs()
    getSocket().emit('typing', selectedRoomId.value)
  })
})

const longtapHandler = () => {
  const { open } = useModal({
    component: VersionModal
  })
  open()
}
const members = computed(() => {
  return room.value.memberIds.map(
    (member: string) => imkit.users[member]?.nickname
  )
})
const textareaDisabled = computed(() => {
  const currRoom = room.value
  if (!currRoom) return false
  if (!currRoom.isSuperuser) return false

  const eligible = currRoom.memberIds.filter(
    (uid: string) => uid !== getUid() && !uid.endsWith('_sub')
  )

  if (eligible.length === 0) return false
  return eligible.every((uid: string) => !!imkit.blockedUsers?.[uid])
})
</script>

<template>
  <div
    v-bind="$attrs"
    class="flex h-dvh flex-col bg-white select-none dark:bg-zinc-800"
    @drop.prevent="onDrop"
    @dragenter="checkIfDroppable"
    @dragover="checkIfDroppable"
  >
    <template v-if="room">
      <search-panel v-if="isSearchInRoomMode" />
      <template v-else>
        <div
          v-touch:longtap="longtapHandler"
          data-testid="chat-header"
          class="flex h-[72px] items-center gap-3 border-b border-solid border-gray-200 px-4 py-4 select-none dark:border-zinc-700"
          :style="styles.chatRoomHeader"
        >
          <ChevronLeft
            v-if="!hasFixedRoomId"
            :size="24"
            class="flex cursor-pointer text-gray-600 sm:hidden! dark:text-gray-300"
            @click="back"
          />
          <avatar-view
            v-if="room.avatars.length === 1"
            :url="room.avatars[0].url"
            :name="room.avatars[0].name"
            class="h-10 w-10 text-xl"
          />
          <div v-else class="relative h-10 w-10">
            <avatar-view
              :url="room.avatars[1].url"
              :name="room.avatars[1].name"
              class="absolute top-0 right-0 h-7 w-7 rounded-xl text-base"
            />
            <avatar-view
              :url="room.avatars[0].url"
              :name="room.avatars[0].name"
              class="absolute bottom-0 left-0 h-[30px] w-[30px] rounded-xl border-2 border-white text-base group-hover:border-gray-100 dark:border-zinc-800"
            />
          </div>
          <div
            class="overflow-hidden text-base text-ellipsis whitespace-nowrap text-gray-900 dark:text-gray-100"
          >
            {{ room.displayName }}
          </div>
          <div class="grow" />
          <Switch v-if="settings.showDarkModeSwitch" round />
          <Search
            v-if="settings.searchInRoomEnabled"
            :size="20"
            class="relative h-5 w-5 cursor-pointer text-gray-600 dark:text-gray-300"
            @click="search"
          />
          <div
            v-if="settings.showEndChatButton"
            class="h-5 w-5 cursor-pointer"
            :title="$t('endChat')"
            @click="openEndChatModal"
          >
            <LogOut class="h-5 w-5 text-gray-600 dark:text-gray-300" />
          </div>
          <div
            v-if="
              (room.type === RoomType.Group &&
                settings.showGroupChatRoomInfoButton) ||
              (room.type === RoomType.Direct &&
                settings.showDirectChatRoomInfoButton)
            "
            class="h-5 w-5 cursor-pointer"
            :title="$t('roomInfo')"
            @click="
              imkit.$patch({
                isRoomInfoVisible: !isRoomInfoVisible
              })
            "
          >
            <Info class="h-5 w-5 text-gray-600 dark:text-gray-300" />
            <slot name="setting" />
          </div>
        </div>
      </template>

      <div
        ref="scrollEl"
        data-testid="chat-scroll-container"
        class="grow overflow-auto p-2"
        :class="{ 'opacity-0': !isInitialLoaded && !isRequesting }"
        style="overflow-anchor: none"
      >
        <div
          class="pointer-events-none sticky top-0 z-10"
          style="height: 0; overflow: visible"
        >
          <div
            v-if="isRequesting"
            data-testid="chat-prepend-spinner"
            class="flex h-12 w-full items-center justify-center"
          >
            <svg
              class="h-6 w-6 animate-spin fill-blue-400 text-gray-200 dark:fill-sky-700 dark:text-gray-700"
              viewBox="0 0 100 101"
              fill="none"
              xmlns="http://www.w3.org/2000/svg"
            >
              <path
                d="M100 50.5908C100 78.2051 77.6142 100.591 50 100.591C22.3858 100.591 0 78.2051 0 50.5908C0 22.9766 22.3858 0.59082 50 0.59082C77.6142 0.59082 100 22.9766 100 50.5908ZM9.08144 50.5908C9.08144 73.1895 27.4013 91.5094 50 91.5094C72.5987 91.5094 90.9186 73.1895 90.9186 50.5908C90.9186 27.9921 72.5987 9.67226 50 9.67226C27.4013 9.67226 9.08144 27.9921 9.08144 50.5908Z"
                fill="currentColor"
              />
              <path
                d="M93.9676 39.0409C96.393 38.4038 97.8624 35.9116 97.0079 33.5539C95.2932 28.8227 92.871 24.3692 89.8167 20.348C85.8452 15.1192 80.8826 10.7238 75.2124 7.41289C69.5422 4.10194 63.2754 1.94025 56.7698 1.05124C51.7666 0.367541 46.6976 0.446843 41.7345 1.27873C39.2613 1.69328 37.813 4.19778 38.4501 6.62326C39.0873 9.04874 41.5694 10.4717 44.0505 10.1071C47.8511 9.54855 51.7191 9.52689 55.5402 10.0491C60.8642 10.7766 65.9928 12.5457 70.6331 15.2552C75.2735 17.9648 79.3347 21.5619 82.5849 25.841C84.9175 28.9121 86.7997 32.2913 88.1811 35.8758C89.083 38.2158 91.5421 39.6781 93.9676 39.0409Z"
                fill="currentFill"
              />
            </svg>
          </div>
        </div>
        <div ref="headerEl" />
        <Virtualizer
          :ref="setVl"
          :data="sortedMessages"
          :scroll-ref="scrollEl || undefined"
          :start-margin="headerH"
          :shift="isPrepending"
          :item-size="66"
          :keep-mounted="keepMountedIndices"
          @scroll="onVlScroll"
        >
          <template #default="{ item }">
            <MessageListCell
              :source="item"
              @popover:open="openPopoverIds.add(item.id)"
              @popover:close="openPopoverIds.delete(item.id)"
            />
          </template>
        </Virtualizer>
      </div>

      <div class="relative flex items-end justify-center gap-3 p-3 pl-3">
        <div
          v-if="isLatestMessageVisible"
          class="absolute -top-10 right-0 left-0 flex h-10 cursor-pointer items-center bg-gray-200/90 px-3 dark:bg-zinc-600/90"
          @click="scrollToBottom"
        >
          <span
            class="overflow-hidden text-base text-ellipsis whitespace-nowrap text-gray-900 dark:text-gray-100"
          >
            {{ room.lastMessage?.senderNickname }}:
            {{ room.lastMessage?.string }}
          </span>
        </div>
        <Plus
          v-if="
            !editingMessageId &&
            (settings.locationInputEnabled ||
              settings.audioInputEnabled ||
              settings.fileInputEnabled)
          "
          class="h-12 w-5 shrink-0 transform cursor-pointer object-contain text-slate-500 transition dark:text-slate-400"
          :class="{ 'rotate-45': showAudioInput }"
          @click="
            () => {
              if (showAudioInput) {
                showAudioInput = false
              } else {
                showActions = true
              }
            }
          "
        />
        <div
          v-if="showActions"
          v-on-click-outside="
            () => {
              showActions = false
            }
          "
          data-id="actions"
          class="absolute bottom-16 left-2 z-10 grid max-w-[240px] grid-cols-3 rounded-lg bg-white p-1.5 text-gray-900 shadow-md dark:bg-zinc-800 dark:text-gray-100"
        >
          <div
            v-for="action in inputActions"
            :key="action.key"
            class="flex min-w-16 cursor-pointer flex-col items-center gap-1 p-2"
            @click="action.onClick"
          >
            <component :is="action.icon" :class="action.iconClass" />
            <div class="mt-1 flex flex-1 items-center">
              <span class="text-center text-xs leading-none">
                {{ $t(action.label) }}
              </span>
            </div>
          </div>
        </div>
        <audio-input v-if="settings.audioInputEnabled && showAudioInput" />
        <div
          v-else
          class="relative flex min-w-0 grow flex-col items-stretch rounded-lg bg-gray-100 px-4 py-3 dark:bg-zinc-700"
        >
          <edit-message-preview />
          <reply-message-preview />
          <div class="flex items-end gap-3 bg-gray-100 dark:bg-zinc-700">
            <div
              class="flex w-0 min-w-0 grow flex-col items-stretch justify-center gap-3"
            >
              <At class="relative flex" :members="members">
                <!-- @vue-ignore At.vue is plain JS, slot types not inferred -->
                <template #embeddedItem="{ current }">
                  <span>@{{ current }}</span>
                </template>
                <div
                  ref="input"
                  data-testid="chat-input"
                  dir="auto"
                  :contenteditable="!textareaDisabled"
                  class="max-h-[calc(1.375rem_*_5)] min-h-[24px] w-full overflow-y-auto text-base break-words whitespace-pre-wrap text-gray-900 outline-none empty:before:pointer-events-none empty:before:text-gray-400 empty:before:content-[attr(data-placeholder)] md:max-h-[min(calc(1.375rem_*_10),40vh)] dark:text-gray-100"
                  :class="{
                    'cursor-not-allowed opacity-50': textareaDisabled
                  }"
                  :data-placeholder="
                    textareaDisabled
                      ? $t('textareaBlockedHint')
                      : $t('TypeMessage')
                  "
                  @keydown.enter="onKeydownEnter"
                  @beforeinput="onBeforeInput"
                  @input="onInput"
                  @paste="onPaste"
                  @compositionstart="onCompositionstart"
                  @compositionend="onCompositionend"
                  @mouseup="formatMenu?.checkSelection()"
                  @keyup="formatMenu?.checkSelection()"
                  @blur="formatMenu?.hideMenu()"
                />
                <!-- Text Format Menu -->
                <TextFormatMenu
                  ref="formatMenu"
                  :input-element="input"
                  @format-applied="onFormatApplied"
                />
              </At>

              <div
                v-if="
                  isLoadingFiles ||
                  images.length > 0 ||
                  isLoadingVideo ||
                  videos.length > 0
                "
                class="flex gap-3 overflow-x-auto pt-2 pr-2"
              >
                <!-- Loading indicator for file processing -->
                <div
                  v-if="isLoadingFiles"
                  class="relative flex h-12 w-12 shrink-0 items-center justify-center rounded-lg bg-gray-200 dark:bg-zinc-600"
                >
                  <Loader2
                    class="h-5 w-5 animate-spin text-gray-500 dark:text-gray-400"
                  />
                </div>

                <TransitionGroup
                  v-if="images.length > 0"
                  tag="div"
                  class="relative flex gap-3"
                  enter-from-class="opacity-0 scale-90"
                  enter-active-class="transition-[opacity,transform] duration-150 ease-out"
                  leave-active-class="transition-opacity duration-150 ease-out absolute"
                  leave-to-class="opacity-0"
                  move-class="transition-transform duration-200 ease-out"
                >
                  <div
                    v-for="(image, index) in images"
                    :key="image.id"
                    class="group relative h-12 w-12 shrink-0"
                  >
                    <img
                      :src="image.thumbnailUrl"
                      class="absolute bottom-0 left-0 h-full w-full cursor-pointer rounded-lg bg-gray-200 object-cover dark:bg-zinc-600"
                      @click="openImageLightbox(index)"
                    />
                    <button
                      class="absolute -top-1.5 -right-1.5 flex h-5 w-5 cursor-pointer items-center justify-center rounded-full bg-black/70 text-white shadow-sm transition-[opacity,transform,background-color] duration-200 ease-out hover:scale-110 hover:bg-black/90 dark:bg-white/80 dark:text-gray-800 dark:hover:bg-white"
                      :class="
                        isMobile
                          ? 'opacity-100'
                          : 'pointer-events-none opacity-0 group-hover:pointer-events-auto group-hover:opacity-100'
                      "
                      @click="removeImageAtIndex(index)"
                    >
                      <X :size="12" :stroke-width="2.5" />
                    </button>
                  </div>
                </TransitionGroup>

                <!-- Loading indicator for video processing -->
                <div
                  v-if="isLoadingVideo"
                  class="relative flex h-12 w-12 shrink-0 items-center justify-center rounded-lg bg-gray-200 dark:bg-zinc-600"
                >
                  <Loader2
                    class="h-5 w-5 animate-spin text-gray-500 dark:text-gray-400"
                  />
                </div>

                <TransitionGroup
                  v-if="videos.length > 0"
                  tag="div"
                  class="relative flex gap-3"
                  enter-from-class="opacity-0 scale-90"
                  enter-active-class="transition-[opacity,transform] duration-150 ease-out"
                  leave-active-class="transition-opacity duration-150 ease-out absolute"
                  leave-to-class="opacity-0"
