import { debounce, throttle } from 'throttle-debounce'
import { ref, watch } from 'vue'
import { useImkitStore } from '../stores/imkit'

export interface UseRoomSearchOptions {
  fetchTask: () => Promise<void>
}

export function useRoomSearch({ fetchTask }: UseRoomSearchOptions) {
  const imkit = useImkitStore()
  const searchKeyword = ref('')
  const searchInput = ref<HTMLInputElement>()
  const isCompositting = ref(false)
  const isAPIRequesting = ref(false)

  const searchRooms = async () => {
    if (searchKeyword.value !== imkit.searchKeyword) {
      if (searchKeyword.value) {
        isAPIRequesting.value = true
        try {
          await imkit.searchRoomsByKeyword(searchKeyword.value)
        } finally {
          isAPIRequesting.value = false
        }
      } else {
        imkit.$patch({ searchKeyword: '' })
        fetchTask()
      }
    }
  }

  const clearSearch = () => {
    searchKeyword.value = ''
    searchRooms()
    searchInput.value?.focus()
  }

  const throttleSearchRooms = throttle(1000, searchRooms)
  const debounceSearchRooms = debounce(500, throttleSearchRooms, {
    atBegin: false
  })

  watch(searchKeyword, debounceSearchRooms)

  return {
    searchKeyword,
    searchInput,
    isCompositting,
    isAPIRequesting,
    searchRooms,
    clearSearch
  }
}
