import { onLongPress } from '@vueuse/core'
import { onUnmounted, ref, watch, type Ref } from 'vue'

/**
 * 檢測裝置是否具有精確指標（滑鼠）或觸控
 */
const detectFinePointer = (): boolean => {
  if (typeof window === 'undefined') {
    return true
  }
  if (typeof window.matchMedia === 'function') {
    return window.matchMedia('(hover: hover) and (pointer: fine)').matches
  }
  if (typeof navigator !== 'undefined') {
    return navigator.maxTouchPoints === 0
  }
  return true
}

export function usePointerDetection() {
  const hasFinePointer = ref(detectFinePointer())
  let cleanupPointerListener: (() => void) | null = null

  if (
    typeof window !== 'undefined' &&
    typeof window.matchMedia === 'function'
  ) {
    const mediaQuery = window.matchMedia('(hover: hover) and (pointer: fine)')
    hasFinePointer.value = mediaQuery.matches
    const handlePointerChange = (event: MediaQueryListEvent) => {
      hasFinePointer.value = event.matches
    }
    if (typeof mediaQuery.addEventListener === 'function') {
      mediaQuery.addEventListener('change', handlePointerChange)
      cleanupPointerListener = () =>
        mediaQuery.removeEventListener('change', handlePointerChange)
    } else if (typeof mediaQuery.addListener === 'function') {
      mediaQuery.addListener(handlePointerChange)
      cleanupPointerListener = () =>
        mediaQuery.removeListener(handlePointerChange)
    }
  }

  onUnmounted(() => {
    cleanupPointerListener?.()
  })

  return {
    hasFinePointer
  }
}

export function useLongPress(
  target: Ref<HTMLElement | null>,
  callback: () => void,
  hasFinePointer: Ref<boolean>
) {
  let stopLongPress: (() => void) | null = null

  const bindLongPress = () => {
    stopLongPress?.()
    stopLongPress = onLongPress(target, callback, {
      modifiers: { prevent: !hasFinePointer.value }
    })
  }

  bindLongPress()
  watch(hasFinePointer, () => {
    bindLongPress()
  })

  onUnmounted(() => {
    stopLongPress?.()
  })

  return {
    bindLongPress
  }
}
