<script setup lang="ts">
import { computed } from 'vue'
import { useVfm, VueFinalModal } from 'vue-final-modal'

// Props
const props = defineProps<{
  fileSizeLimit: number
}>()
const vfm = useVfm()
function formatSize(bytes: number): string {
  const MB = 1_000_000
  const KB = 1_000
  if (bytes >= MB) {
    return `${Math.round(bytes / MB)} MB`
  }
  if (bytes >= KB) {
    return `${Math.round(bytes / KB)} KB`
  }
  return `${bytes} B`
}
const limitText = computed(() => formatSize(props.fileSizeLimit))
</script>

<template>
  <vue-final-modal
    class="flex items-center justify-center"
    content-class="bg-white dark:bg-zinc-800 min-w-[200px] max-w-full rounded-xl p-5 flex flex-col gap-3 w-[300px]"
    content-transition="vfm-fade"
    overlay-transition="vfm-fade"
  >
    <div class="mb-1 text-xl font-medium text-gray-700 dark:text-gray-300">
      {{ $t('fileSizeLimitTitle', 'File too large') }}
    </div>
    <div class="text-gray-500 dark:text-gray-400">
      {{ $t('fileSizeLimitMessage', [limitText]) }}
    </div>
    <div class="mt-2 flex items-center justify-center gap-2">
      <button
        class="h-10 w-[100px] grow rounded-lg border border-gray-200 text-base dark:border-stone-400 dark:text-stone-400"
        @click="vfm.closeAll()"
      >
        {{ $t('confirm') }}
      </button>
    </div>
  </vue-final-modal>
</template>
