<script setup lang="ts">
import { Folder as FolderIcon } from 'lucide-vue-next'
import { computed } from 'vue'
import { useVfm, VueFinalModal } from 'vue-final-modal'
import Folder from '../classes/folder'
import { useImkitStore } from '../stores/imkit'
import CloseSvg from './svgs/CloseSvg.vue'
const vfm = useVfm()
const props = defineProps<{ roomId: string }>()
const imkit = useImkitStore()
const sortedFolders = computed(() =>
  imkit.sortedFolderIds
    .map((id: string) => imkit.folders[id])
    .filter((folder: Folder) => folder)
)
const submit = (folderId: string) => {
  if (!props.roomId) return
  imkit.addRoomToFolder({
    roomId: props.roomId,
    folderId
  })
}
</script>

<template>
  <vue-final-modal
    class="flex items-center justify-center"
    content-class="bg-white dark:bg-zinc-800 rounded-xl p-5 flex flex-col gap-3 w-[360px] relative max-h-80vh overflow-y-auto"
    content-transition="vfm-fade"
    overlay-transition="vfm-fade"
  >
    <div
      class="mb-1 flex items-center justify-between text-xl font-medium text-gray-700 dark:text-gray-300"
    >
      {{ $t('addToFolder') }}
      <button class="flex items-center justify-center" @click="vfm.closeAll()">
        <CloseSvg class="h-7 w-7" />
      </button>
    </div>
    <div
      v-for="folder in sortedFolders"
      :key="folder.id"
      class="group relative flex cursor-pointer items-center gap-3 rounded-lg bg-slate-200 p-2 dark:bg-slate-700"
      @click="
        () => {
          submit(folder.id)
          vfm.closeAll()
        }
      "
    >
      <FolderIcon :size="30" class="text-gray-600 dark:text-gray-300" />
      {{ folder.name }}
    </div>
  </vue-final-modal>
</template>
